PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE multiplexes(
	mux_id INTEGER PRIMARY KEY ASC,
	delsys,
	orbital,
	polarisation,
	frequency,
	srate,
	tsid,
	onid,
	last_seen,
	global_id
);
CREATE TABLE services(
	service_id INTEGER PRIMARY KEY ASC,
	service_name,
	last_capture,
	last_header
);
CREATE TABLE service_mapper(
	sm_id INTEGER PRIMARY KEY ASC,
	mux_id,
	pid,
	service_name,
	svcname,
	last_seen,
	last_capture,
	last_header,
	last_size,
	UNIQUE(mux_id, pid)
);
CREATE TABLE mux_locks(
	mux_id INTEGER NOT NULL,
	user_name,
	locked_until,
	UNIQUE(mux_id)
);
CREATE TABLE mux_cor(
	corr_id INTEGER PRIMARY KEY ASC,
	mux_id INTEGER NOT NULL,
	user_name,
	local_uuid,
	update_id
);
CREATE INDEX idx_service_mapper_mux_id on service_mapper(mux_id);
CREATE INDEX idx_service_mapper_pid on service_mapper(pid);
CREATE INDEX idx_service_mapper_service_name on service_mapper(service_name);
CREATE INDEX idx_services_name ON services(service_name);
CREATE INDEX idx_mux_cor_mux_id_user_name ON mux_cor (mux_id, user_name);
CREATE INDEX idx_mux_cor_uuid_user_name ON mux_cor (local_uuid, user_name);
COMMIT;
